with open(f"{BASE}/runs/round78/batches.json",encoding="utf-8") as f:
    batches=json.load(f)
ids=batches["B04"]
assert set(E.keys())==set(ids), (set(ids)-set(E.keys()), set(E.keys())-set(ids))
for cid in ids:
    with open(f"{BASE}/inputs-dev12/{cid}.json",encoding="utf-8") as f:
        card=json.load(f)
    txt,extra,conf=E[cid]
    if "tradition" in card:
        first=card["tradition"]; sysu=card["tradition"]
    elif "system" in card:
        first=card["system"]; sysu=card["system"]
    else:
        first="卡面未标注 tradition 字段，按题面体裁自决"; sysu="bazi（题面四柱命造，自决）" if cid.startswith("BZ") else "自决"
    basis=f"{first}\nsystems_used: {sysu}\n{extra}"
    obj={"case_id":cid,"prediction_text":txt,"basis":basis,"confidence":conf,
         "trigger":{"changed_main":False,"reserve_used":False,"disputed":False,"reason":""}}
    with open(f"{OUT}/{cid}.json","w",encoding="utf-8") as f:
        json.dump(obj,f,ensure_ascii=False,indent=1)
print("B04 written", len(ids))
